ipt-linux-x64\": \"7.0.2\",\n    \"@typescript/typescript-win32-arm64\": \"7.0.2\",\n    \"@typescript/typescript-win32-x64\": \"7.0.2\"\n  },\n  \"peerDependencies\": {\n    \"@pkl-community/pkl\": \"0.30.2\",\n    \"vue\": \">=2.6.0 || >=3.6.0-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@pkl-community/pkl\": {\n      \"optional\": true\n    },\n    \"vue\": {\n      \"optional\": true\n    }\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"directory\": \"npm/cli\",\n    \"type\": \"git\",\n    \"url\": \"https://github.com/ubugeeei-prod/vize\"\n  },\n  \"type\": \"module\",\n  \"types\": \"./dist/index.d.mts\",\n  \"typescript\": {\n    \"contentMapper\": {\n      \"compilerOptions\": [\n        \"noUnusedLocals\"\n      ],\n      \"exec\": [\n        \"node\",\n        \"./bin/vize\",\n        \"content-mapper\"\n      ]\n    }\n  },\n  \"version\": \"0.457.0\",\n  \"scripts\": {\n    \"build\": \"vp run --workspace-root generate:rule-types && vp pack\",\n    \"check\": \"vp check src tests vite.config.ts\",\n    \"check:fix\": \"vp check --fix src tests vite.config.ts\",\n    \"fmt\": \"vp fmt --write src tests vite.config.ts\",\n    \"generate:rule-types\": \"vp run --workspace-root generate:rule-types\",\n    \"test\": \"vp pack && vp test run tests/config.test.ts tests/vite-project-config.test.ts tests/define-config.test.ts tests/corsa-runtime.test.ts tests/setup.test.ts tests/setup-oxlint-config.test.ts tests/init.test.ts tests/init-frameworks.test.ts tests/init-tsconfig.test.ts tests/init-prompt.test.ts tests/init-config-free.test.ts tests/init-workspace.test.ts\"\n  }\n}",
